(1725, 498, 'Total materials', '[{\"raw\": \"101x clay\", \"type\": \"material\", \"quantity\": 101, \"item\": \"clay\", \"links\": [{\"href\": \"/index.php/Clay\", \"text\": \"clay\", \"title\": \"Clay\"}]}, {\"raw\": \"101x stone bricks\", \"type\": \"material\", \"quantity\": 101, \"item\": \"stone bricks\", \"links\": [{\"href\": \"/index.php/Stone_brick\", \"text\": \"stone bricks\", \"title\": \"Stone brick\"}]}, {\"raw\": \"10x cochineals\", \"type\": \"material\", \"quantity\": 10, \"item\": \"cochineals\", \"links\": [{\"href\": \"/index.php/Cochineal\", \"text\": \"cochineals\", \"title\": \"Cochineal\"}]}]', '<td>\n<ul><li>101x <a href=\"/index.php/Clay\" title=\"Clay\">clay</a></li>\n<li>101x <a href=\"/index.php/Stone_brick\" title=\"Stone brick\">stone bricks</a></li>\n<li>10x <a href=\"/index.php/Cochineal\" title=\"Cochineal\">cochineals</a></li></ul>\n</td>'),
