(1753, 515, 'Creation', '[{\"raw\": \"Activate trowel\", \"type\": \"step\", \"action\": \"activate\", \"links\": [{\"href\": \"/index.php/Activate\", \"text\": \"Activate\", \"title\": \"Activate\"}, {\"href\": \"/index.php/Trowel\", \"text\": \"trowel\", \"title\": \"Trowel\"}]}, {\"raw\": \"Right-click wall plan\", \"type\": \"step\", \"action\": \"right-click\", \"links\": [{\"href\": \"/index.php/Wall_plan\", \"text\": \"wall plan\", \"title\": \"Wall plan\"}]}, {\"raw\": \"Open menu > Build > Stone double door\", \"type\": \"step\", \"links\": [{\"href\": \"/index.php/Context_menu\", \"text\": \"menu\", \"title\": \"Context menu\"}]}]', '<td>\n<ul><li><a href=\"/index.php/Activate\" title=\"Activate\">Activate</a> <a href=\"/index.php/Trowel\" title=\"Trowel\">trowel</a></li><li>Right-click <a href=\"/index.php/Wall_plan\" title=\"Wall plan\">wall plan</a></li>\n<li>Open <a href=\"/index.php/Context_menu\" title=\"Context menu\">menu</a> &gt; Build &gt; Stone double door</li>\n</ul>\n</td>'),
(1754, 515, 'Total materials', '[{\"raw\": \"20x mortars (40.00 kg)\", \"type\": \"material\", \"quantity\": 20, \"item\": \"mortars (40.00 kg)\", \"links\": [{\"href\": \"/index.php/Mortar\", \"text\": \"mortars\", \"title\": \"Mortar\"}]}, {\"raw\": \"20x Stone bricks\", \"type\": \"material\", \"quantity\": 20, \"item\": \"Stone bricks\", \"links\": [{\"href\": \"/index.php/Stone_brick\", \"text\": \"Stone bricks\", \"title\": \"Stone brick\"}]}]', '<td>\n<ul><li>20x <a href=\"/index.php/Mortar\" title=\"Mortar\">mortars</a> (40.00 kg)</li>\n<li>20x <a href=\"/index.php/Stone_brick\" title=\"Stone brick\">Stone bricks</a></li></ul>\n</td>'),
(1755, 515, 'Result', '[{\"raw\": \"Stone double door\"}]', '<td>\n<ul><li><b>Stone double door</b></li></ul>\n</td>'),
(1756, 515, 'Skill and improvement', '[{\"raw\": \"Uses Masonry skill\", \"type\": \"skill\", \"links\": [{\"href\": \"/index.php/Masonry\", \"text\": \"Masonry\", \"title\": \"Masonry\"}]}, {\"raw\": \"30 Masonry required\", \"type\": \"skill\", \"links\": [{\"href\": \"/index.php/Masonry\", \"text\": \"Masonry\", \"title\": \"Masonry\"}]}, {\"raw\": \"Improve with Stone brick\", \"type\": \"skill\", \"links\": [{\"href\": \"/index.php/Improve\", \"text\": \"Improve\", \"title\": \"Improve\"}]}]', '<td>\n<ul><li>Uses <a href=\"/index.php/Masonry\" title=\"Masonry\">Masonry</a> skill</li>\n<li>30 <a href=\"/index.php/Masonry\" title=\"Masonry\">Masonry</a> required</li>\n<li><a href=\"/index.php/Improve\" title=\"Improve\">Improve</a> with Stone brick</li></ul>\n</td>'),
(1757, 515, 'Notes', '[{\"raw\": \"You must have 1 Stone brick and 1 mortar in inventory to build the wall.\", \"links\": [{\"href\": \"/index.php/Stone_brick\", \"text\": \"Stone brick\", \"title\": \"Stone brick\"}, {\"href\": \"/index.php/Mortar\", \"text\": \"mortar\", \"title\": \"Mortar\"}]}]', '<td>\n<ul><li>You must have 1 <a href=\"/index.php/Stone_brick\" title=\"Stone brick\">Stone brick</a> and 1 <a href=\"/index.php/Mortar\" title=\"Mortar\">mortar</a> in inventory to build the wall.</li></ul>\n</td>'),
(1758, 516, 'Creation', '[{\"raw\": \"Activate Mallet or Hammer\", \"type\": \"step\", \"action\": \"activate\", \"links\": [{\"href\": \"/index.php/Activate\", \"text\": \"Activate\", \"title\": \"Activate\"}, {\"href\": \"/index.php/Mallet\", \"text\": \"Mallet\", \"title\": \"Mallet\"}, {\"href\": \"/index.php/Hammer\", \"text\": \"Hammer\", \"title\": \"Hammer\"}]}, {\"raw\": \"Right-click Wall plan\", \"type\": \"step\", \"action\": \"right-click\", \"links\": [{\"href\": \"/index.php/Wall_plan\", \"text\": \"Wall plan\", \"title\": \"Wall plan\"}]}, {\"raw\": \"Open menu > Build > Wooden double door\", \"type\": \"step\", \"links\": [{\"href\": \"/index.php/Context_menu\", \"text\": \"menu\", \"title\": \"Context menu\"}]}]', '<td>\n<ul><li><a href=\"/index.php/Activate\" title=\"Activate\">Activate</a> <a href=\"/index.php/Mallet\" title=\"Mallet\">Mallet</a> or <a href=\"/index.php/Hammer\" title=\"Hammer\">Hammer</a></li><li>Right-click <a href=\"/index.php/Wall_plan\" title=\"Wall plan\">Wall plan</a></li>\n<li>Open <a href=\"/index.php/Context_menu\" title=\"Context menu\">menu</a> &gt; Build &gt; Wooden double door</li>\n</ul>\n</td>'),
