(1761, 516, 'Skill and improvement', '[{\"raw\": \"Uses Carpentry skill\", \"type\": \"skill\", \"links\": [{\"href\": \"/index.php/Carpentry\", \"text\": \"Carpentry\", \"title\": \"Carpentry\"}]}]', '<td>\n<ul><li>Uses <a href=\"/index.php/Carpentry\" title=\"Carpentry\">Carpentry</a> skill</li></ul>\n</td>'),
(1762, 516, 'Notes', '[{\"raw\": \"You must have 1 plank and 1 large nails in inventory to build the wall.\", \"links\": [{\"href\": \"/index.php/Plank\", \"text\": \"plank\", \"title\": \"Plank\"}, {\"href\": \"/index.php/Large_nails\", \"text\": \"large nails\", \"title\": \"Large nails\"}]}]', '<td>\n<ul><li>You must have 1 <a href=\"/index.php/Plank\" title=\"Plank\">plank</a> and 1 <a href=\"/index.php/Large_nails\" title=\"Large nails\">large nails</a> in inventory to build the wall.</li></ul>\n</td>'),
