(1781, 523, 'Creation', '[{\"raw\": \"Activate Mallet , Hammer or Trowel\", \"type\": \"step\", \"action\": \"activate\", \"links\": [{\"href\": \"/index.php/Activate\", \"text\": \"Activate\", \"title\": \"Activate\"}, {\"href\": \"/index.php/Mallet\", \"text\": \"Mallet\", \"title\": \"Mallet\"}, {\"href\": \"/index.php/Hammer\", \"text\": \"Hammer\", \"title\": \"Hammer\"}, {\"href\": \"/index.php/Trowel\", \"text\": \"Trowel\", \"title\": \"Trowel\"}]}, {\"raw\": \"Right-click Tile Border\", \"type\": \"step\", \"action\": \"right-click\", \"links\": [{\"href\": \"/index.php/Tile_Border\", \"text\": \"Tile Border\", \"title\": \"Tile Border\"}]}, {\"raw\": \"Open menu > Fence >\\nStone\\n> Build Low stone wall\", \"type\": \"step\", \"links\": [{\"href\": \"/index.php/Context_menu\", \"text\": \"menu\", \"title\": \"Context menu\"}]}]', '<td>\n<ul><li><a href=\"/index.php/Activate\" title=\"Activate\">Activate</a> <a href=\"/index.php/Mallet\" title=\"Mallet\">Mallet</a>, <a href=\"/index.php/Hammer\" title=\"Hammer\">Hammer</a> or <a href=\"/index.php/Trowel\" title=\"Trowel\">Trowel</a></li><li>Right-click <a class=\"mw-redirect\" href=\"/index.php/Tile_Border\" title=\"Tile Border\">Tile Border</a></li>\n<li>Open <a href=\"/index.php/Context_menu\" title=\"Context menu\">menu</a> &gt; Fence &gt;\nStone\n&gt; Build Low stone wall</li>\n</ul>\n</td>'),
(1782, 523, 'Total materials', '[{\"raw\": \"10x stone shards (200.00 kg)\", \"type\": \"material\", \"quantity\": 10, \"item\": \"stone shards (200.00 kg)\", \"links\": [{\"href\": \"/index.php/Stone_shards\", \"text\": \"stone shards\", \"title\": \"Stone shards\"}]}]', '<td>\n<ul><li>10x <a href=\"/index.php/Stone_shards\" title=\"Stone shards\">stone shards</a> (200.00 kg)</li></ul>\n</td>'),
