(1784, 523, 'Skill and improvement', '[{\"raw\": \"Uses Masonry skill\", \"type\": \"skill\", \"links\": [{\"href\": \"/index.php/Masonry\", \"text\": \"Masonry\", \"title\": \"Masonry\"}]}, {\"raw\": \"Improve with stone shards\", \"type\": \"skill\", \"links\": [{\"href\": \"/index.php/Improve\", \"text\": \"Improve\", \"title\": \"Improve\"}]}]', '<td>\n<ul><li>Uses <a href=\"/index.php/Masonry\" title=\"Masonry\">Masonry</a> skill</li>\n<li><a href=\"/index.php/Improve\" title=\"Improve\">Improve</a> with stone shards</li></ul>\n</td>'),
(1785, 523, 'Notes', '[{\"raw\": \"You must have at least one stone shards in your inventory to start building it.\", \"links\": [{\"href\": \"/index.php/Stone_shards\", \"text\": \"stone shards\", \"title\": \"Stone shards\"}, {\"href\": \"/index.php/Inventory\", \"text\": \"inventory\", \"title\": \"Inventory\"}]}]', '<td>\n<ul><li>You must have at least one <a href=\"/index.php/Stone_shards\" title=\"Stone shards\">stone shards</a> in your <a href=\"/index.php/Inventory\" title=\"Inventory\">inventory</a> to start building it.</li></ul>\n</td>'),
