(1908, 558, 'Notes', '[{\"raw\": \"You must have 1 Stone brick and 1 mortar in inventory to build the wall.\", \"links\": [{\"href\": \"/index.php/Stone_brick\", \"text\": \"Stone brick\", \"title\": \"Stone brick\"}, {\"href\": \"/index.php/Mortar\", \"text\": \"mortar\", \"title\": \"Mortar\"}]}]', '<td>\n<ul><li>You must have 1 <a href=\"/index.php/Stone_brick\" title=\"Stone brick\">Stone brick</a> and 1 <a href=\"/index.php/Mortar\" title=\"Mortar\">mortar</a> in inventory to build the wall.</li></ul>\n</td>'),
(1909, 559, 'Creation', '[{\"raw\": \"Activate Mallet or Hammer\", \"type\": \"step\", \"action\": \"activate\", \"links\": [{\"href\": \"/index.php/Activate\", \"text\": \"Activate\", \"title\": \"Activate\"}, {\"href\": \"/index.php/Mallet\", \"text\": \"Mallet\", \"title\": \"Mallet\"}, {\"href\": \"/index.php/Hammer\", \"text\": \"Hammer\", \"title\": \"Hammer\"}]}, {\"raw\": \"Right-click Wall plan\", \"type\": \"step\", \"action\": \"right-click\", \"links\": [{\"href\": \"/index.php/Wall_plan\", \"text\": \"Wall plan\", \"title\": \"Wall plan\"}]}, {\"raw\": \"Open menu > Build > Wooden arched wall\", \"type\": \"step\", \"links\": [{\"href\": \"/index.php/Context_menu\", \"text\": \"menu\", \"title\": \"Context menu\"}]}]', '<td>\n<ul><li><a href=\"/index.php/Activate\" title=\"Activate\">Activate</a> <a href=\"/index.php/Mallet\" title=\"Mallet\">Mallet</a> or <a href=\"/index.php/Hammer\" title=\"Hammer\">Hammer</a></li><li>Right-click <a href=\"/index.php/Wall_plan\" title=\"Wall plan\">Wall plan</a></li>\n<li>Open <a href=\"/index.php/Context_menu\" title=\"Context menu\">menu</a> &gt; Build &gt; <b>Wooden arched wall</b></li>\n</ul>\n</td>'),
