(2068, 601, 'Creation', '[{\"raw\": \"Activate Leggat\", \"type\": \"step\", \"action\": \"activate\", \"links\": [{\"href\": \"/index.php/Activate\", \"text\": \"Activate\", \"title\": \"Activate\"}, {\"href\": \"/index.php/Leggat\", \"text\": \"Leggat\", \"title\": \"Leggat\"}]}, {\"raw\": \"Right-click Reed (0.05 kg) or Mixed grass (0.05 kg)\", \"type\": \"step\", \"action\": \"right-click\", \"links\": [{\"href\": \"/index.php/Reed\", \"text\": \"Reed\", \"title\": \"Reed\"}, {\"href\": \"/index.php/Mixed_grass\", \"text\": \"Mixed grass\", \"title\": \"Mixed grass\"}]}, {\"raw\": \"Open submenu \\\"Create > Construction material \\\"\", \"type\": \"step\", \"action\": \"submenu\", \"links\": [{\"href\": \"/index.php/Construction_material\", \"text\": \"Construction material\", \"title\": \"Construction material\"}]}]', '<td>\n<ul><li><a href=\"/index.php/Activate\" title=\"Activate\">Activate</a> <a href=\"/index.php/Leggat\" title=\"Leggat\">Leggat</a></li><li>Right-click <a href=\"/index.php/Reed\" title=\"Reed\">Reed</a> (0.05 kg) or <a href=\"/index.php/Mixed_grass\" title=\"Mixed grass\">Mixed grass</a> (0.05 kg)</li>\n<li>Open submenu \"Create &gt; <a class=\"mw-redirect\" href=\"/index.php/Construction_material\" title=\"Construction material\">Construction material</a>\"</li>\n</ul>\n</td>'),
