(2143, 619, 'Creation', '[{\"raw\": \"Activate mallet\", \"type\": \"step\", \"action\": \"activate\", \"links\": [{\"href\": \"/index.php/Activate\", \"text\": \"Activate\", \"title\": \"Activate\"}, {\"href\": \"/index.php/Mallet\", \"text\": \"mallet\", \"title\": \"Mallet\"}]}, {\"raw\": \"Right-click floor plan\", \"type\": \"step\", \"action\": \"right-click\", \"links\": [{\"href\": \"/index.php/Floor_plan\", \"text\": \"floor plan\", \"title\": \"Floor plan\"}]}, {\"raw\": \"Open submenu \\\"Create > Wooden plank opening \\\"\", \"type\": \"step\", \"action\": \"submenu\"}]', '<td>\n<ul><li><a href=\"/index.php/Activate\" title=\"Activate\">Activate</a> <a href=\"/index.php/Mallet\" title=\"Mallet\">mallet</a></li><li>Right-click <a href=\"/index.php/Floor_plan\" title=\"Floor plan\">floor plan</a></li>\n<li>Open submenu \"Create &gt; <a class=\"mw-selflink selflink\">Wooden plank opening</a>\"</li>\n</ul>\n</td>'),
