(2626, 752, 'Creation', '[{\"raw\": \"Activate iron lump (1.00 kg)\", \"type\": \"step\", \"action\": \"activate\", \"links\": [{\"href\": \"/index.php/Activate\", \"text\": \"Activate\", \"title\": \"Activate\"}, {\"href\": \"/index.php/Iron_lump\", \"text\": \"iron lump\", \"title\": \"Iron lump\"}]}, {\"raw\": \"Right-click large anvil\", \"type\": \"step\", \"action\": \"right-click\", \"links\": [{\"href\": \"/index.php/Large_anvil\", \"text\": \"large anvil\", \"title\": \"Large anvil\"}]}, {\"raw\": \"Open submenu \\\"Create > Construction material \\\"\", \"type\": \"step\", \"action\": \"submenu\", \"links\": [{\"href\": \"/index.php/Construction_material\", \"text\": \"Construction material\", \"title\": \"Construction material\"}]}]', '<td>\n<ul><li><a href=\"/index.php/Activate\" title=\"Activate\">Activate</a> <a href=\"/index.php/Iron_lump\" title=\"Iron lump\">iron lump</a> (1.00 kg)</li><li>Right-click <a href=\"/index.php/Large_anvil\" title=\"Large anvil\">large anvil</a></li>\n<li>Open submenu \"Create &gt; <a class=\"mw-redirect\" href=\"/index.php/Construction_material\" title=\"Construction material\">Construction material</a>\"</li>\n</ul>\n</td>'),
