(2628, 752, 'Skill and improvement', '[{\"raw\": \"Uses Blacksmithing skill\", \"type\": \"skill\", \"links\": [{\"href\": \"/index.php/Blacksmithing\", \"text\": \"Blacksmithing\", \"title\": \"Blacksmithing\"}]}, {\"raw\": \"Cannot be improved\", \"type\": \"skill\", \"links\": [{\"href\": \"/index.php/Improve\", \"text\": \"improved\", \"title\": \"Improve\"}]}]', '<td>\n<ul><li>Uses <a href=\"/index.php/Blacksmithing\" title=\"Blacksmithing\">Blacksmithing</a> skill</li>\n<li>Cannot be <a href=\"/index.php/Improve\" title=\"Improve\">improved</a></li></ul>\n</td>'),
(2629, 753, 'Creation', '[{\"raw\": \"Activate Mallet , Hammer or Trowel\", \"type\": \"step\", \"action\": \"activate\", \"links\": [{\"href\": \"/index.php/Activate\", \"text\": \"Activate\", \"title\": \"Activate\"}, {\"href\": \"/index.php/Mallet\", \"text\": \"Mallet\", \"title\": \"Mallet\"}, {\"href\": \"/index.php/Hammer\", \"text\": \"Hammer\", \"title\": \"Hammer\"}, {\"href\": \"/index.php/Trowel\", \"text\": \"Trowel\", \"title\": \"Trowel\"}]}, {\"raw\": \"Right-click Tile Border\", \"type\": \"step\", \"action\": \"right-click\", \"links\": [{\"href\": \"/index.php/Tile_Border\", \"text\": \"Tile Border\", \"title\": \"Tile Border\"}]}, {\"raw\": \"Open menu > Fence >\\nIron\\n> Build Chain fence\", \"type\": \"step\", \"links\": [{\"href\": \"/index.php/Context_menu\", \"text\": \"menu\", \"title\": \"Context menu\"}]}]', '<td>\n<ul><li><a href=\"/index.php/Activate\" title=\"Activate\">Activate</a> <a href=\"/index.php/Mallet\" title=\"Mallet\">Mallet</a>, <a href=\"/index.php/Hammer\" title=\"Hammer\">Hammer</a> or <a href=\"/index.php/Trowel\" title=\"Trowel\">Trowel</a></li><li>Right-click <a class=\"mw-redirect\" href=\"/index.php/Tile_Border\" title=\"Tile Border\">Tile Border</a></li>\n<li>Open <a href=\"/index.php/Context_menu\" title=\"Context menu\">menu</a> &gt; Fence &gt;\nIron\n&gt; Build Chain fence</li>\n</ul>\n</td>'),
(2630, 753, 'Total materials', '[{\"raw\": \"10x stone brick\", \"type\": \"material\", \"quantity\": 10, \"item\": \"stone brick\", \"links\": [{\"href\": \"/index.php/Stone_brick\", \"text\": \"stone brick\", \"title\": \"Stone brick\"}]}, {\"raw\": \"6x Large chain link\", \"type\": \"material\", \"quantity\": 6, \"item\": \"Large chain link\", \"links\": [{\"href\": \"/index.php/Large_chain_link\", \"text\": \"Large chain link\", \"title\": \"Large chain link\"}]}]', '<td>\n<ul><li>10x <a href=\"/index.php/Stone_brick\" title=\"Stone brick\">stone brick</a></li>\n<li>6x <a href=\"/index.php/Large_chain_link\" title=\"Large chain link\">Large chain link</a></li></ul>\n</td>'),
