(2692, 772, 'Total materials', '[{\"raw\": \"4x planks\", \"type\": \"material\", \"quantity\": 4, \"item\": \"planks\", \"links\": [{\"href\": \"/index.php/Planks\", \"text\": \"planks\", \"title\": \"Planks\"}]}, {\"raw\": \"1x small nails\", \"type\": \"material\", \"quantity\": 1, \"item\": \"small nails\", \"links\": [{\"href\": \"/index.php/Small_nails\", \"text\": \"small nails\", \"title\": \"Small nails\"}]}, {\"raw\": \"4x shafts\", \"type\": \"material\", \"quantity\": 4, \"item\": \"shafts\", \"links\": [{\"href\": \"/index.php/Shafts\", \"text\": \"shafts\", \"title\": \"Shafts\"}]}]', '<td>\n<ul><li>4x <a class=\"mw-redirect\" href=\"/index.php/Planks\" title=\"Planks\">planks</a></li>\n<li>1x <a href=\"/index.php/Small_nails\" title=\"Small nails\">small nails</a></li>\n<li>4x <a class=\"mw-redirect\" href=\"/index.php/Shafts\" title=\"Shafts\">shafts</a></li></ul>\n</td>'),
