(2694, 772, 'Skill and improvement', '[{\"raw\": \"Uses Fine carpentry skill\", \"type\": \"skill\", \"links\": [{\"href\": \"/index.php/Fine_carpentry\", \"text\": \"Fine carpentry\", \"title\": \"Fine carpentry\"}]}, {\"raw\": \"Improved using Fine carpentry tools and materials\", \"type\": \"skill\", \"links\": [{\"href\": \"/index.php/Improve\", \"text\": \"Improved\", \"title\": \"Improve\"}, {\"href\": \"/index.php/Fine_carpentry\", \"text\": \"Fine carpentry\", \"title\": \"Fine carpentry\"}]}]', '<td>\n<ul><li>Uses <a href=\"/index.php/Fine_carpentry\" title=\"Fine carpentry\">Fine carpentry</a> skill</li>\n<li><a href=\"/index.php/Improve\" title=\"Improve\">Improved</a> using <a href=\"/index.php/Fine_carpentry\" title=\"Fine carpentry\">Fine carpentry</a> tools and materials</li></ul>\n</td>'),
(2695, 772, 'Properties', '[{\"raw\": \"Appears as decoration.\", \"type\": \"property\"}, {\"raw\": \"Can be dyed using 1235g of paint.\", \"type\": \"property\", \"links\": [{\"href\": \"/index.php/Dye\", \"text\": \"dyed\", \"title\": \"Dye\"}]}]', '<td>\n<ul><li>Appears as decoration.</li>\n<li>Can be <a href=\"/index.php/Dye\" title=\"Dye\">dyed</a> using 1235g of paint.</li></ul>\n</td>'),
(2696, 773, 'Creation', '[{\"raw\": \"Activate carving knife\", \"type\": \"step\", \"action\": \"activate\", \"links\": [{\"href\": \"/index.php/Activate\", \"text\": \"Activate\", \"title\": \"Activate\"}, {\"href\": \"/index.php/Carving_knife\", \"text\": \"carving knife\", \"title\": \"Carving knife\"}]}, {\"raw\": \"Right-click log (2.00 kg)\", \"type\": \"step\", \"action\": \"right-click\", \"links\": [{\"href\": \"/index.php/Log\", \"text\": \"log\", \"title\": \"Log\"}]}, {\"raw\": \"Open submenu \\\"Create > Construction material \\\"\", \"type\": \"step\", \"action\": \"submenu\", \"links\": [{\"href\": \"/index.php/Construction_material\", \"text\": \"Construction material\", \"title\": \"Construction material\"}]}]', '<td>\n<ul><li><a href=\"/index.php/Activate\" title=\"Activate\">Activate</a> <a href=\"/index.php/Carving_knife\" title=\"Carving knife\">carving knife</a></li><li>Right-click <a href=\"/index.php/Log\" title=\"Log\">log</a> (2.00 kg)</li>\n<li>Open submenu \"Create &gt; <a class=\"mw-redirect\" href=\"/index.php/Construction_material\" title=\"Construction material\">Construction material</a>\"</li>\n</ul>\n</td>'),
