(2698, 773, 'Skill and improvement', '[{\"raw\": \"Uses carpentry skill\", \"type\": \"skill\", \"links\": [{\"href\": \"/index.php/Carpentry\", \"text\": \"carpentry\", \"title\": \"Carpentry\"}]}, {\"raw\": \"Cannot be improved\", \"type\": \"skill\", \"links\": [{\"href\": \"/index.php/Improve\", \"text\": \"improved\", \"title\": \"Improve\"}]}]', '<td>\n<ul><li>Uses <a href=\"/index.php/Carpentry\" title=\"Carpentry\">carpentry</a> skill</li>\n<li>Cannot be <a href=\"/index.php/Improve\" title=\"Improve\">improved</a></li></ul>\n</td>'),
