(2709, 777, 'Creation', '[{\"raw\": \"Activate Mallet or Hammer\", \"type\": \"step\", \"action\": \"activate\", \"links\": [{\"href\": \"/index.php/Activate\", \"text\": \"Activate\", \"title\": \"Activate\"}, {\"href\": \"/index.php/Mallet\", \"text\": \"Mallet\", \"title\": \"Mallet\"}, {\"href\": \"/index.php/Hammer\", \"text\": \"Hammer\", \"title\": \"Hammer\"}]}, {\"raw\": \"Right-click Wall plan\", \"type\": \"step\", \"action\": \"right-click\", \"links\": [{\"href\": \"/index.php/Wall_plan\", \"text\": \"Wall plan\", \"title\": \"Wall plan\"}]}, {\"raw\": \"Open menu > Build > Timber framed window\", \"type\": \"step\", \"links\": [{\"href\": \"/index.php/Context_menu\", \"text\": \"menu\", \"title\": \"Context menu\"}]}]', '<td>\n<ul><li><a href=\"/index.php/Activate\" title=\"Activate\">Activate</a> <a href=\"/index.php/Mallet\" title=\"Mallet\">Mallet</a> or <a href=\"/index.php/Hammer\" title=\"Hammer\">Hammer</a></li><li>Right-click <a href=\"/index.php/Wall_plan\" title=\"Wall plan\">Wall plan</a></li>\n<li>Open <a href=\"/index.php/Context_menu\" title=\"Context menu\">menu</a> &gt; Build &gt; Timber framed window</li>\n</ul>\n</td>'),
(2710, 777, 'Total materials', '[{\"raw\": \"5x Wooden beam\", \"type\": \"material\", \"quantity\": 5, \"item\": \"Wooden beam\", \"links\": [{\"href\": \"/index.php/Wooden_beam\", \"text\": \"Wooden beam\", \"title\": \"Wooden beam\"}]}, {\"raw\": \"20x Clay\", \"type\": \"material\", \"quantity\": 20, \"item\": \"Clay\", \"links\": [{\"href\": \"/index.php/Clay\", \"text\": \"Clay\", \"title\": \"Clay\"}]}, {\"raw\": \"10x Mixed grass\", \"type\": \"material\", \"quantity\": 10, \"item\": \"Mixed grass\", \"links\": [{\"href\": \"/index.php/Mixed_grass\", \"text\": \"Mixed grass\", \"title\": \"Mixed grass\"}]}]', '<td>\n<ul><li>5x <a href=\"/index.php/Wooden_beam\" title=\"Wooden beam\">Wooden beam</a></li>\n<li>20x <a href=\"/index.php/Clay\" title=\"Clay\">Clay</a></li>\n<li>10x <a href=\"/index.php/Mixed_grass\" title=\"Mixed grass\">Mixed grass</a></li></ul>\n</td>'),
