(3255, 922, 'Notes', '[{\"raw\": \"You must have 1 Stone brick and 1 mortar in inventory to build the wall.\", \"links\": [{\"href\": \"/index.php/Stone_brick\", \"text\": \"Stone brick\", \"title\": \"Stone brick\"}, {\"href\": \"/index.php/Mortar\", \"text\": \"mortar\", \"title\": \"Mortar\"}]}]', '<td>\n<ul><li>You must have 1 <a href=\"/index.php/Stone_brick\" title=\"Stone brick\">Stone brick</a> and 1 <a href=\"/index.php/Mortar\" title=\"Mortar\">mortar</a> in inventory to build the wall.</li></ul>\n</td>'),
(3256, 923, 'Creation', '[{\"raw\": \"Activate shaft (1.00 kg)\", \"type\": \"step\", \"action\": \"activate\", \"links\": [{\"href\": \"/index.php/Activate\", \"text\": \"Activate\", \"title\": \"Activate\"}, {\"href\": \"/index.php/Shaft\", \"text\": \"shaft\", \"title\": \"Shaft\"}]}, {\"raw\": \"Right-click square piece of cloth (4.50 kg)\", \"type\": \"step\", \"action\": \"right-click\", \"links\": [{\"href\": \"/index.php/Square_piece_of_cloth\", \"text\": \"square piece of cloth\", \"title\": \"Square piece of cloth\"}]}, {\"raw\": \"Open submenu \\\"Create > Flags \\\"\", \"type\": \"step\", \"action\": \"submenu\", \"links\": [{\"href\": \"/index.php/Flags\", \"text\": \"Flags\", \"title\": \"Flags\"}]}]', '<td>\n<ul><li><a href=\"/index.php/Activate\" title=\"Activate\">Activate</a> <a href=\"/index.php/Shaft\" title=\"Shaft\">shaft</a> (1.00 kg)</li><li>Right-click <a href=\"/index.php/Square_piece_of_cloth\" title=\"Square piece of cloth\">square piece of cloth</a> (4.50 kg)</li>\n<li>Open submenu \"Create &gt; <a class=\"mw-redirect\" href=\"/index.php/Flags\" title=\"Flags\">Flags</a>\"</li>\n</ul>\n</td>'),
