(5061, 1694, 'Creation', '[{\"raw\": \"Activate Clay\", \"type\": \"step\", \"action\": \"activate\", \"links\": [{\"href\": \"/index.php/Activate\", \"text\": \"Activate\", \"title\": \"Activate\"}, {\"href\": \"/index.php/Clay\", \"text\": \"Clay\", \"title\": \"Clay\"}]}, {\"raw\": \"Right-click Stone parapet\", \"type\": \"step\", \"action\": \"right-click\", \"links\": [{\"href\": \"/index.php/Stone_parapet\", \"text\": \"Stone parapet\", \"title\": \"Stone parapet\"}]}, {\"raw\": \"Open menu > Render fence\", \"type\": \"step\", \"links\": [{\"href\": \"/index.php/Context_menu\", \"text\": \"menu\", \"title\": \"Context menu\"}]}]', '<td>\n<ul><li><a href=\"/index.php/Activate\" title=\"Activate\">Activate</a> <a href=\"/index.php/Clay\" title=\"Clay\">Clay</a></li><li>Right-click <a href=\"/index.php/Stone_parapet\" title=\"Stone parapet\">Stone parapet</a></li>\n<li>Open <a href=\"/index.php/Context_menu\" title=\"Context menu\">menu</a> &gt; Render fence</li>\n</ul>\n</td>'),
