(6568, 2168, 'Creation', '[{\"raw\": \"Activate Jar , Bucket , Cauldron , Water skin or Small barrel\", \"type\": \"step\", \"action\": \"activate\", \"links\": [{\"href\": \"/index.php/Activate\", \"text\": \"Activate\", \"title\": \"Activate\"}, {\"href\": \"/index.php/Jar\", \"text\": \"Jar\", \"title\": \"Jar\"}, {\"href\": \"/index.php/Bucket\", \"text\": \"Bucket\", \"title\": \"Bucket\"}, {\"href\": \"/index.php/Cauldron\", \"text\": \"Cauldron\", \"title\": \"Cauldron\"}, {\"href\": \"/index.php/Water_skin\", \"text\": \"Water skin\", \"title\": \"Water skin\"}, {\"href\": \"/index.php/Small_barrel\", \"text\": \"Small barrel\", \"title\": \"Small barrel\"}]}, {\"raw\": \"Right-click Cow , Sheep , or Bison Select Milk\", \"type\": \"step\", \"action\": \"right-click\", \"links\": [{\"href\": \"/index.php/Cow\", \"text\": \"Cow\", \"title\": \"Cow\"}, {\"href\": \"/index.php/Sheep\", \"text\": \"Sheep\", \"title\": \"Sheep\"}, {\"href\": \"/index.php/Bison\", \"text\": \"Bison\", \"title\": \"Bison\"}]}, {\"raw\": \"Select Milk\", \"type\": \"step\"}]', '<td>\n<ul><li><a href=\"/index.php/Activate\" title=\"Activate\">Activate</a> <a class=\"mw-redirect\" href=\"/index.php/Jar\" title=\"Jar\">Jar</a>, <a class=\"mw-redirect\" href=\"/index.php/Bucket\" title=\"Bucket\">Bucket</a>, <a href=\"/index.php/Cauldron\" title=\"Cauldron\">Cauldron</a>, <a href=\"/index.php/Water_skin\" title=\"Water skin\">Water skin</a> or <a href=\"/index.php/Small_barrel\" title=\"Small barrel\">Small barrel</a></li><li>Right-click <a href=\"/index.php/Cow\" title=\"Cow\">Cow</a>, <a href=\"/index.php/Sheep\" title=\"Sheep\">Sheep</a>, or <a href=\"/index.php/Bison\" title=\"Bison\">Bison</a>\n<ul><li>Select <i>Milk</i></li></ul>\n</li></ul>\n</td>'),
