(10105, 3225, 'Creation', '[{\"raw\": \"Activate girth\", \"type\": \"step\", \"action\": \"activate\", \"links\": [{\"href\": \"/index.php/Activate\", \"text\": \"Activate\", \"title\": \"Activate\"}, {\"href\": \"/index.php/Girth\", \"text\": \"girth\", \"title\": \"Girth\"}]}, {\"raw\": \"Right-click large saddle seat\", \"type\": \"step\", \"action\": \"right-click\", \"links\": [{\"href\": \"/index.php/Large_saddle_seat\", \"text\": \"large saddle seat\", \"title\": \"Large saddle seat\"}]}, {\"raw\": \"Open submenu \\\"Create > Animal equipment \\\"\", \"type\": \"step\", \"action\": \"submenu\", \"links\": [{\"href\": \"/index.php/Animal_equipment\", \"text\": \"Animal equipment\", \"title\": \"Animal equipment\"}]}]', '<td>\n<ul><li><a href=\"/index.php/Activate\" title=\"Activate\">Activate</a> <a href=\"/index.php/Girth\" title=\"Girth\">girth</a></li><li>Right-click <a href=\"/index.php/Large_saddle_seat\" title=\"Large saddle seat\">large saddle seat</a></li>\n<li>Open submenu \"Create &gt; <a class=\"mw-redirect\" href=\"/index.php/Animal_equipment\" title=\"Animal equipment\">Animal equipment</a>\"</li>\n</ul>\n</td>'),
(10106, 3225, 'Total materials', '[{\"raw\": \"1x girth\", \"type\": \"material\", \"quantity\": 1, \"item\": \"girth\", \"links\": [{\"href\": \"/index.php/Girth\", \"text\": \"girth\", \"title\": \"Girth\"}]}, {\"raw\": \"1x large saddle seat\", \"type\": \"material\", \"quantity\": 1, \"item\": \"large saddle seat\", \"links\": [{\"href\": \"/index.php/Large_saddle_seat\", \"text\": \"large saddle seat\", \"title\": \"Large saddle seat\"}]}, {\"raw\": \"1x stirrups\", \"type\": \"material\", \"quantity\": 1, \"item\": \"stirrups\", \"links\": [{\"href\": \"/index.php/Stirrups\", \"text\": \"stirrups\", \"title\": \"Stirrups\"}]}]', '<td>\n<ul><li>1x <a href=\"/index.php/Girth\" title=\"Girth\">girth</a></li>\n<li>1x <a href=\"/index.php/Large_saddle_seat\" title=\"Large saddle seat\">large saddle seat</a></li>\n<li>1x <a href=\"/index.php/Stirrups\" title=\"Stirrups\">stirrups</a></li></ul>\n</td>'),
